## Why This Is Asked

This question tests understanding of dynamic imports, caching strategies, concurrency handling, and import maps in the browser. It evaluates the ability to handle circular dependencies and cross-origin concerns while maintaining strict singleton semantics.

## Key Concepts

- Dynamic import() and module namespace objects
- Per-origin caching with inFlight deduplication
- Circular dependency handling without deadlocks
- Import maps specifier remapping
- Preload strategy and race condition management

## Code Example

```javascript
// Per-origin cache keyed by origin + URL
const moduleCache = new Map();
const inFlight = new Map();

async function loadModule(url, importMap) {
  const cacheKey = new URL(url).origin + new URL(url).pathname;

  if (moduleCache.has(cacheKey)) {
    return moduleCache.get(cacheKey);
  }

  if (inFlight.has(cacheKey)) {
    return inFlight.get(cacheKey);
  }

  const loadPromise = performLoad(url, importMap, cacheKey);
  inFlight.set(cacheKey, loadPromise);

  const module = await loadPromise;
  moduleCache.set(cacheKey, module);
  inFlight.delete(cacheKey);

  return module;
}

async function performLoad(url, importMap, cacheKey) {
  if (importMap) {
    const script = document.createElement('script');
    script.type = 'importmap';
    script.textContent = JSON.stringify(importMap);
    document.head.appendChild(script);
  }

  return import(url);
}

function preload(url, importMap) {
  return loadModule(url, importMap);
}
```

## Minimal A/B Circular Import Example

```javascript
// a.js
export const a = 'module A';
import('./b.js').then(b => console.log(b.b));

export const a2 = 'also A';

// b.js
export const b = 'module B';
import('./a.js').then(a => console.log(a.a));

export const b2 = 'also B';
```

The circular dependency resolves because JavaScript exports are hoisted—both modules complete loading, and the exported values become available once both module records are initialized.

This question assesses the ability to integrate fetch, WebSocket, and Service Worker into a cohesive offline-first architecture. Key concepts include: offline-first patterns using Service Workers with stale-while-revalidate strategies; WebSocket lifecycle management with exponential backoff reconnection; efficient DOM updates through batched diffing; and maintaining data coherence between REST history and live WebSocket streams.

## Code Example

```javascript
// REST fetch wrapper
async function fetchHistory(id) {
  const res = await fetch(`/api/chat/${id}/history?limit=100`);
  const messages = await res.json();
  await idb.put('chat-db', 'messages', messages);
  return messages;
}

// WebSocket wrapper with reconnection
function createChatSocket(id) {
  const ws = new WebSocket(`/ws/chat/${id}`);
  let reconnectDelay = 1000;

  ws.onclose = () => {
    setTimeout(() => {
      reconnectDelay = Math.min(reconnectDelay * 2, 30000);
      createChatSocket(id);
    }, reconnectDelay);
  };

  ws.onmessage = (e) => handleNewMessage(JSON.parse(e.data));
  return ws;
}

// DOM diff updater
function handleNewMessage(msg) {
  const list = document.getElementById('message-list');
  const existing = Array.from(list.children);
  const newMsgEl = createMessageElement(msg);

  if (!existing.find(el => el.dataset.id === msg.id)) {
    list.appendChild(newMsgEl);
  }
}

// Service Worker caching strategy (stale-while-revalidate)
self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request)
      .then(cached => {
        const fetchPromise = fetch(e.request).then(response => {
          caches.open('chat-v1').then(cache => cache.put(e.request, response.clone()));
          return response;
        });
        return cached || fetchPromise;
      })
  );
});
```

## Why This Is Asked
Tests ability to design a clean, responsive CSS grid with accessible motion for a news app.

## Key Concepts
- CSS Grid responsive columns (repeat, minmax)
- Image aspect ratio and overlay
- CSS-only entrance animations and stagger
- prefers-reduced-motion and keyboard focus

## Code Example
```css
.grid{ display: grid; grid-template-columns: repeat(3, 1fr); gap:1rem; }
.card{ position: relative; border-radius:8px; overflow:hidden; opacity:0; transform: translateY(8px); animation: fadeUp .4s forwards; }
.thumb{ aspect-ratio: 4/3; background:#ccc; }
@media (max-width: 900px){ .grid{ grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px){ .grid{ grid-template-columns: 1fr; } }
@keyframes fadeUp{ to{ opacity:1; transform:none; } }
.grid > :nth-child(1){ animation-delay:.0s; }
.grid > :nth-child(2){ animation-delay:.05s; }
.grid > :nth-child(3){ animation-delay:.1s; }
@media (prefers-reduced-motion: reduce){ .grid > *{ animation:none; opacity:1; transform:none; } }
```

