## Why This Is Asked
Tests the candidate's ability to design a real-time, per-tenant UI with robust dataflow, per-tenant memoization, and careful rendering to avoid churn during rapid tenant switches.

## Key Concepts
- useSyncExternalStore for external streams per tenant
- memoized selectors with composite keys (tenantId, topN)
- React.memo on row components
- virtualization with react-window for lists
- per-tenant context switching and cleanup

## Code Example
```javascript
// Stream wrapper (per-tenant)
function createTenantStreamStore() {
  const listeners = new Map();
  let state = {};
  return {
    subscribe(tenantId, cb) {
      if (!listeners.has(tenantId)) listeners.set(tenantId, new Set());
      listeners.get(tenantId).add(cb);
      return () => listeners.get(tenantId).delete(cb);
    },
    emit(record) {
      const { tenantId } = record;
      state[tenantId] = state[tenantId] || [];
      state[tenantId].push(record);
      // keep small window for demo purposes
      (listeners.get(tenantId) || new Set()).forEach((cb) => cb(state[tenantId]));
    },
    getSnapshot(tenantId) {
      return (state[tenantId] || []).slice();
    }
  };
}

// Selector (per-tenant top-N with 5-min window)
const topNSelector = (state, tenantId, topN) => {
  const now = Date.now();
  const items = (state[tenantId] || []);
  const windowItems = items.filter(i => now - i.ts <= 5 * 60 * 1000);
  return windowItems
    .slice()
    .sort((a, b) => b.score - a.score)
    .slice(0, topN);
};

// LeaderboardRow (memoized)
const LeaderboardRow = React.memo(function Row({ item, rank }) {
  return (
    <div className="row" role="listitem" aria-label={`#${rank} ${item.userId}`}>#{rank} {item.userId} — {item.score}</div>
  );
});

// Panel integration (pseudocode)
function PerTenantLeaderboardPanel({ topN = 10 }) {
  const { tenantId } = useContext(TenantContext);
  const streamStore = useMemo(createTenantStreamStore, []);
  const snapshot = useSyncExternalStore(
    (cb) => streamStore.subscribe(tenantId, cb),
    () => streamStore.getSnapshot(tenantId),
    () => streamStore.getSnapshot(tenantId)
  );
  const topList = useMemo(() => topNSelector(snapshot, tenantId, topN), [snapshot, tenantId, topN]);
  return (
    <List height={400} itemCount={topList.length} itemSize={40} width={300}>
      {({ index, style }) => (
        <LeaderboardRow item={topList[index]} rank={index + 1} style={style} />
      )}
    </List>
  );
}
```

## Follow-up Questions
- How would you test cleanup on rapid tenant switches?
- How would you handle missing ts clocks or out-of-order events in a live stream?

## Why This Is Asked

Tests the ability to design a robust per-key caching layer with concurrency control and real-time updates, mirroring production frontend concerns in large apps.

## Key Concepts

- Closure-based state encapsulation
- Deduplicating concurrent async calls
- In-flight concurrency control and queuing
- Per-key TTL caching
- Real-time update propagation into cache

## Code Example

```javascript
function createPresenceCache(fetchPresence, { ttl = 30000, maxInFlight = 5, onUpdate } = {}) {
  const cache = new Map();
  const inFlight = new Map();
  const waitQueue = [];

  function drain() {
    if (inFlight.size >= maxInFlight || waitQueue.length === 0) return;
    const next = waitQueue.shift();
    if (!next) return;
    const { userId, resolve } = next;
    const p = fetchPresence(userId).then(status => {
      cache.set(userId, { status, expires: Date.now() + ttl });
      if (onUpdate) onUpdate(userId, status);
      inFlight.delete(userId);
      resolve(status);
      drain();
      return status;
    }).catch(err => { inFlight.delete(userId); throw err; });
    inFlight.set(userId, p);
  }

  async function getPresence(userId) {
    const cached = cache.get(userId);
    if (cached && cached.expires > Date.now()) return cached.status;
    return new Promise((resolve, reject) => {
      waitQueue.push({ userId, resolve, reject });
      drain();
    }).then(status => status);
  }

  function clear(userId) {
    cache.delete(userId);
  }

  return { getPresence, clear };
}
```

